-- bio_plus shots — A1 «Истоки» (22 shots, summer 2008, Mogilev)
-- Prerequisite: seed_bio_plus.sql already run (project + scenes + characters + profiles exist).
-- Joins project by slug + scene by sceneKey. Idempotent: re-running on the same scene will create duplicate shots,
-- so re-run only after running seed_bio_plus.sql (which DELETEs project CASCADE).

BEGIN;

INSERT INTO shots (id, "projectId", "sceneId", "shotCode", "promptFields", "shotType", "cameraAngle", "cameraMove", "storyBeat", "narrativeFunction", "vignetteSlug", "isBroll", "isIconic", "timeOfDay", "paletteKey", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, p.id, s.id, v.shot_code, v.prompt_fields::jsonb, v.shot_type, v.camera_angle, v.camera_move, v.story_beat, v.narrative_function, v.vignette_slug, v.is_broll, v.is_iconic, v.time_of_day, v.palette_key, NOW(), NOW()
FROM projects p
JOIN scenes s ON s."projectId" = p.id AND s."sceneKey" = 'act_01_origins'
CROSS JOIN (VALUES
  ('A1_SH01', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, extreme wide shot from high rooftop angle over Mashinostroiteley district of Mogilev in summer 2008, rows of five-storey Khrushchev-era panel apartment blocks in pale grey and pale yellow flat roofs with TV antennas, golden tops of birch and poplar trees, white poplar fluff drifting visible as small dots, sodium-warm afternoon haze, distant smokestacks of Mogilev industrial zone faintly visible, shadows pulling east at thirty-degree angle, hard ink outline on every roof edge antenna treeline, cell-shaded yellow and dusty-rose color blocks with subtle cross-hatching in shadow, EWS high angle locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Лето две тысячи восьмого, Могилёв, район Машиностроителей, тебе двадцать восемь лет"}$pp$, 'EWS', 'high', 'static', 'setup', 'iconic', NULL, TRUE, TRUE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH02', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, wide shot of inner courtyard between five-storey panel apartment blocks in Mogilev summer 2008, {HEROINE_ELENA_AGE_28} walks with small white baby pram across courtyard, beside her {DAUGHTER_OLDER_AGE_04} holding side of pram with right hand small cotton sundress in pale yellow, broken asphalt with weeds at edges single rusting playground swing-set in background, warm sodium afternoon light long shadows pulling east, poplar fluff drifting in air, hard ink outline cell-shaded color, WS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Развод оформлен пять недель назад, старшая четырёхлетняя, младшей четыре месяца"}$pp$, 'WS', 'eye', 'static', 'setup', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH03', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, medium shot of {HEROINE_ELENA_AGE_28} pushing white baby pram along shaded sidewalk of Pervomayskaya street in Mogilev, {DAUGHTER_OLDER_AGE_04} walking beside pram holding its side, ahead green-painted facade of small Soviet-style pharmacy with faded sign reading АПТЕКА ЗДОРОВЬЕ in cyrillic above door, shaded side of street dappled tree-shadow on asphalt warm sodium afternoon light bleeding beyond trees, hard ink outline cell-shaded color blocks with dappled hatching for tree shadow, MS eye level tracking laterally 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты идёшь в аптеку Здоровье на Первомайской, там работает твоя мать"}$pp$, 'MS', 'eye', 'track_lateral', 'setup', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH04', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, close-up of {MOM_GALINA_AGE_60} behind small Soviet pharmacy counter, grey pharmacist lab coat over beige knit cardigan visible at collar, thin steel-link chain holding reading glasses around neck glasses resting on chest of lab coat, thinning grey-streaked hair pinned back severely tired grey-blue eyes with deep crow''s feet small dark mole on left jawline (matching daughter), behind her warm wooden pharmacy shelves with rows of medicines soft sodium-yellow ceiling light, hard ink outline cell-shaded skin two-tone with subtle hatching under eyes and along jaw, CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Галина Степановна, серый халат, очки на тонкой серебряной цепочке"}$pp$, 'CU', 'eye', 'static', 'setup', 'character', 'mom_galina', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH05', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, over-the-shoulder shot from behind {MOM_GALINA_AGE_60} looking past her grey lab coat collar at pharmacy counter, on glass counter green-and-white box of children''s milk formula labeled НУТРИЛАК in cyrillic next to small bottle of paracetamol syrup, on customer side {HEROINE_ELENA_AGE_28} stands with small white baby pram beside her, shallow depth of field — Galina shoulder soft in foreground counter and heroine sharp, warm sodium overhead pharmacy light cool daylight from front window, hard ink outline cell-shaded color blocks cyrillic typography on box with crisp ink lines, OTS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Тебе нужна детская смесь и парацетамол для младшей, в кошельке сорок рублей"}$pp$, 'OTS', 'eye', 'static', 'setup', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH06', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, extreme close-up of {HEROINE_ELENA_AGE_28} hands holding small worn brown leather wallet open, inside wallet crumpled 10-rouble Belarusian note several copper 20-kopeck coins one single 200-rouble note, fingertips counting coins slight tremor in index finger, pharmacy counter edge just visible below wallet, warm sodium overhead light catching metal of coins, hard ink outline on coin edges wallet seams fingernails, cell-shaded color brown leather warm coin copper warm catchlight paper notes pale, ECU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Зарплаты бывшего мужа в этом месяце не было, он перестал отвечать с понедельника"}$pp$, 'ECU', 'eye', 'static', 'setup', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH07', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, wide shot of interior of small Soviet pharmacy on Pervomayskaya in Mogilev, {HEROINE_ELENA_AGE_28} at counter on left baby pram beside her, behind her queue of six people in summer dress three elderly women in floral house dresses each holding prescription slip middle-aged man in checked shirt young woman holding small child of about 18 months, warm wooden pharmacy shelves on both walls sodium ceiling lights, hard ink outline on every figure and shelf edge cell-shaded color blocks in two tones, WS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "За тобой стоят шесть человек, бабушки с рецептами, женщина с ребёнком на руках"}$pp$, 'WS', 'eye', 'static', 'setup', 'atmosphere', NULL, TRUE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH08', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, medium shot of {NEIGHBOR_TAMARA_AGE_55} in pharmacy queue just ahead of heroine, she is turning in three-quarter view toward camera/heroine recognition starting on her face, bright floral summer dress in faded blues and pinks canvas shoulder bag with leather handles, salt-and-pepper hair pinned up loosely showing grey roots at temples, burgundy lipstick painted slightly past natural lip line gold-tone clip earrings, warm sodium pharmacy ceiling light soft cool window-fill from right, hard ink outline on silhouette dress floral pattern bag cell-shaded with subtle cross-hatching on dress fabric, MS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Перед тобой тётя Тамара из пятой квартиры, она поворачивается и узнаёт тебя"}$pp$, 'MS', 'eye', 'static', 'setup', 'character', 'neighbor_tamara', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH09', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, close-up of {NEIGHBOR_TAMARA_AGE_55} face in three-quarter view, soft round face kind worried hazel eyes with crow''s feet, burgundy lipstick painted slightly past upper lip outline imperfection deliberate and visible, grey roots showing at temples where hair pinned up, faint blush on cheekbones from summer warmth, gold-tone clip earring visible at right ear, warm sodium overhead light from pharmacy ceiling soft cool fill from front window, hard ink outline on lip contour eye contours earring cell-shaded skin two-tone with subtle hatching under eyes, CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Она спрашивает про дочку, про развод, про то, как ты справляешься одна"}$pp$, 'CU', 'eye', 'static', 'setup', 'character', 'neighbor_tamara', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH10', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, extreme close-up of {NEIGHBOR_TAMARA_AGE_55} right hand emerging from open mouth of canvas shoulder bag with leather handles, fingers holding small white plastic pill bottle with forest-green label, bag interior dim with yellow shopping receipt visible inside, slight tremor of recognition in heroine hand reaching toward it from right edge of frame, warm sodium pharmacy light catching white plastic of bottle cool shadow inside bag, hard ink outline on bottle canvas bag stitching fingers, cell-shaded color blocks white bottle warm green label flat color canvas bag cool grey-brown, ECU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Она достаёт из сумки маленькую белую баночку с зелёной этикеткой и протягивает тебе"}$pp$, 'ECU', 'eye', 'static', 'catalyst', 'plot', 'neighbor_tamara', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH11', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, extreme close-up pushing in slowly on small white plastic pill bottle held up between thumb and forefinger, on its forest-green-and-white label cyrillic typography in bold sans-serif BIOPLUS — MAGNIY+ (БИОПЛЮС — МАГНИЙ+), beneath in smaller text 30 КАПСУЛ ПРОБНИК БЕСПЛАТНО, small green silhouette of leaf icon at top-left of label, beige-cream background of pharmacy interior warm sodium catchlight on bottle plastic, hard ink outline crisp on every cyrillic letterform and leaf icon, cell-shaded color blocks white plastic bottle forest-green label ink-black text, ECU eye level slow push-in 16:9 iconic composition", "negativeRef": "{NEG}", "narrationRu": "На этикетке написано БиоПлюс Магний плюс, пробник, тридцать капсул, бесплатно"}$pp$, 'ECU', 'eye', 'push_in', 'catalyst', 'iconic', NULL, TRUE, TRUE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH12', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, over-the-shoulder shot from behind {HEROINE_ELENA_AGE_28} looking at {NEIGHBOR_TAMARA_AGE_55} ahead in queue, Tamara turned three-quarters her burgundy-lipsticked mouth moving in mid-sentence, in heroine hand small white BIO+ Magnesium bottle held loosely, shallow focus heroine shoulder soft in foreground Tamara face sharp, warm sodium pharmacy ceiling light queue of women behind Tamara out of focus, hard ink outline on Tamara face bottle in foreground heroine shoulder cell-shaded coloring, OTS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "У нас в доме представительница, говорит Тамара, она проводит дни здоровья бесплатно"}$pp$, 'OTS', 'eye', 'static', 'catalyst', 'character', 'neighbor_tamara', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH13', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, close-up of {HEROINE_ELENA_AGE_28} face in three-quarter view, expression uncertain eyes flick down to own hand holding bottle then back up at Tamara off-frame, in foreground bottom edge right hand visible holding small white BIO+ Magnesium bottle fingertips closing around it, younger smooth skin brighter pale grey-blue eyes no grey hair very faint sunburn on nose bridge from summer outside, warm sodium pharmacy light from above cool fill from front window, hard ink outline on face bottle fingertips cell-shaded skin two-tone with subtle hatching under eyes, CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты колеблешься, ты не любишь, когда тебе что-то дают просто так, но берёшь"}$pp$, 'CU', 'eye', 'static', 'catalyst', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH14', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, wide shot of {HEROINE_ELENA_AGE_28} pushing white baby pram out of pharmacy door onto Pervomayskaya street pavement, {DAUGHTER_OLDER_AGE_04} walking beside pram still holding its side, behind them green-painted pharmacy facade with cyrillic sign АПТЕКА ЗДОРОВЬЕ, above them sky hot summer washed-out white-blue at 31°C heat shimmer visible at edges of road, short sharp shadows directly under each figure, warm-yellow sodium daylight dust haze in air, hard ink outline on figures pram pharmacy sign cell-shaded color blocks, WS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты выходишь из аптеки в три часа дня, на улице тридцать один градус"}$pp$, 'WS', 'eye', 'static', 'setup', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH15', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, medium shot of {HEROINE_ELENA_AGE_28} pushing white baby pram along shaded side of Pervomayskaya street, {DAUGHTER_OLDER_AGE_04} holding side of pram in silence, dappled tree-shadow across asphalt ribbon of warm sodium sun on unshaded side beyond, in heroine right pocket of cotton summer sundress a faint bulge of small white pill bottle, camera tracks laterally at eye level matching slow walk, hard ink outline on figures dappled cross-hatching for tree shadow cell-shaded color, MS eye level track_lateral 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты идёшь по тенистой стороне обратно, старшая держится за коляску и молчит"}$pp$, 'MS', 'eye', 'track_lateral', 'setup', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH16', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, extreme close-up from low angle of pocket of cotton summer sundress in pale yellow, inside pocket curved corner of small white plastic pill bottle pushing fabric out, weave of cotton fabric visible slight sunlight bleeding through thin material, bottle inside catching sliver of warm sodium light from above, hard ink outline on fabric weave bottle curve, cell-shaded color pale yellow cotton with subtle cross-hatching white bottle warm-toned, ECU low angle locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Баночка лежит у тебя в кармане сарафана, она лёгкая, ты её почти не чувствуешь"}$pp$, 'ECU', 'low', 'static', 'setup', 'atmosphere', NULL, TRUE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH17', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, extreme wide establishing shot of small Soviet-era kitchen in Mogilev panel apartment 2008, yellow floral wallpaper with faded daisy pattern covering walls, round wooden table in centre under single hanging pendant lamp with beige fabric shade, table covered with faded green-and-white checked plastic tablecloth, window on right looking out onto inner courtyard with summer light coming through, old gas stove against far wall small porcelain sink under window, empty wooden high-chair against wall old TV-set Рубин on stand in doorway, hard ink outline on every furniture edge wallpaper pattern abstracted to flat shapes cell-shaded color in three tones, EWS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Дома на кухне жёлтые обои в цветочек и круглый стол под выцветшей клеёнкой"}$pp$, 'EWS', 'eye', 'static', 'setup', 'atmosphere', NULL, TRUE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH18', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, medium shot of {HEROINE_ELENA_AGE_28} standing at kitchen table, right hand placing small white BIO+ Magnesium pill bottle on green-and-white checked tablecloth, in doorway to living room behind her back of {DAUGHTER_OLDER_AGE_04} head visible facing old Рубин TV set showing flickering colored Soyuzmultfilm cartoons, warm afternoon daylight through kitchen window from right, hard ink outline on heroine silhouette bottle kitchen elements TV silhouette cell-shaded color blocks two-tone, MS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты ставишь баночку на стол, старшая в комнате у телевизора, мультфильмы Союзмультфильма"}$pp$, 'MS', 'eye', 'static', 'setup', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH19', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, extreme close-up pushing in slowly on small white BIO+ Magnesium bottle label, cyrillic fine print directly readable ПО ОДНОЙ КАПСУЛЕ В ДЕНЬ БИОЛОГИЧЕСКИ АКТИВНАЯ ДОБАВКА БЕЗ РЕЦЕПТА, forest-green label background with white sans-serif typography, slight specular highlight on rounded white plastic shoulder of bottle, behind bottle green-and-white checked tablecloth out of focus, hard ink outline crisp on every cyrillic letterform cell-shaded color white bottle forest-green label ink-black text, ECU eye level slow push-in 16:9", "negativeRef": "{NEG}", "narrationRu": "По одной капсуле в день, говорит инструкция, биологически активная добавка, без рецепта"}$pp$, 'ECU', 'eye', 'push_in', 'setup', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH20', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, close-up of {HEROINE_ELENA_AGE_28} face and hands at kitchen table, both hands working white plastic cap of BIO+ Magnesium bottle just unscrewed, nose tilted slightly toward open bottle as smell rises, subtle expression of curiosity eyes half-closed catching smell, warm afternoon sidelight from window on right, hard ink outline on face hands bottle cap cell-shaded skin two tones with very subtle hatching at bridge of nose, CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты откручиваешь крышку, запах травы, что-то лимонное, что-то горьковатое"}$pp$, 'CU', 'eye', 'static', 'setup', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH21', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, extreme close-up from high angle of single small dark-amber gelatin capsule resting in centre of {HEROINE_ELENA_AGE_28} pale palm, behind palm at bottom of frame corner of chipped white enamel cup with cold tap water inside, soft warm afternoon kitchen light from above the right, hard ink outline on capsule palm creases cup rim, cell-shaded color warm pale skin dark amber capsule cool white cup highlight, ECU high angle locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты кладёшь её на язык и запиваешь водой из-под крана, глотаешь"}$pp$, 'ECU', 'high', 'static', 'catalyst', 'character', 'heroine_elena', FALSE, FALSE, 'summer_afternoon_2008', 'A1_sodium_summer'),
  ('A1_SH22', $pp${"positivePrompt": "{STYLE}, {PALETTE_A1}, close-up of {HEROINE_ELENA_AGE_28} sitting at kitchen table forty minutes after taking magnesium capsule, face in three-quarter view eyes half-closed in mild physical surprise faint involuntary smile pulling at corner of mouth — first smile in entire film, warm afternoon kitchen light from window on right golden cast on cheek and hair, soft cool ambient fill from yellow wallpaper bouncing back, hard ink outline on face hair table edge in foreground cell-shaded skin two-tone with very subtle hatching just above navel area where warm knot sensation begins (sensory anchor), CU eye level slow push-in 16:9 iconic composition", "negativeRef": "{NEG}", "narrationRu": "Через сорок минут ты чувствуешь сладкий тёплый узел чуть выше живота, впервые"}$pp$, 'CU', 'eye', 'push_in', 'catalyst', 'iconic', 'heroine_elena', FALSE, TRUE, 'summer_afternoon_2008', 'A1_sodium_summer')
) AS v(shot_code, prompt_fields, shot_type, camera_angle, camera_move, story_beat, narrative_function, vignette_slug, is_broll, is_iconic, time_of_day, palette_key)
WHERE p.slug = 'bio_plus';

COMMIT;
